package app.quietreader.discovery;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FeedExposureTrackerTest {
    @Test public void onlyContinuouslyVisibleRowsMature(){FeedExposureTracker tracker=new FeedExposureTracker();tracker.viewport(Map.of("visible",.5,"sliver",.49),100);assertEquals(1300,tracker.dueAt());assertTrue(tracker.matured(1299).isEmpty());assertEquals(Set.of("visible"),tracker.matured(1300));assertEquals(-1,tracker.dueAt());}
    @Test public void quickPassAndUnseenCandidatesNeverCount(){FeedExposureTracker tracker=new FeedExposureTracker();tracker.viewport(Map.of("passed",1.0),10);tracker.viewport(Map.of("current",1.0),300);assertEquals(Set.of("current"),tracker.matured(1500));assertEquals(-1,tracker.dueAt());}
    @Test public void partialOcclusionBreaksContinuity(){FeedExposureTracker tracker=new FeedExposureTracker();tracker.viewport(Map.of("a",1.0),0);tracker.viewport(Map.of("a",.4),1100);assertEquals(-1,tracker.dueAt());tracker.viewport(Map.of("a",.8),1200);assertTrue(tracker.matured(2399).isEmpty());assertEquals(Set.of("a"),tracker.matured(2400));}
    @Test public void repeatedLayoutDoesNotResetDwellOrRecordTwice(){FeedExposureTracker tracker=new FeedExposureTracker();for(int n=0;n<12;n++)tracker.viewport(Map.of("a",1.0),n*100);assertEquals(Set.of("a"),tracker.matured(1200));tracker.viewport(Map.of("a",1.0),1400);assertEquals(-1,tracker.dueAt());assertTrue(tracker.matured(6000).isEmpty());}
    @Test public void pauseDiscardsHiddenTimeButPreservesPresentationDedup(){FeedExposureTracker tracker=new FeedExposureTracker();tracker.viewport(Map.of("a",1.0),0);tracker.pause();assertTrue(tracker.matured(9000).isEmpty());tracker.viewport(Map.of("a",1.0),9000);assertEquals(Set.of("a"),tracker.matured(10200));tracker.pause();tracker.viewport(Map.of("a",1.0),12000);assertEquals(-1,tracker.dueAt());}
    @Test public void explicitPresentationCanRecordAgain(){FeedExposureTracker tracker=new FeedExposureTracker();tracker.viewport(Map.of("a",1.0),0);assertEquals(Set.of("a"),tracker.matured(1200));tracker.newPresentation();tracker.viewport(Map.of("a",1.0),1300);assertEquals(Set.of("a"),tracker.matured(2500));}
    @Test public void eachRowHasIndependentContinuousDwell(){FeedExposureTracker tracker=new FeedExposureTracker();tracker.viewport(Map.of("a",1.0),0);tracker.viewport(Map.of("a",.8,"b",.7),500);assertEquals(Set.of("a"),tracker.matured(1200));assertEquals(1700,tracker.dueAt());assertEquals(Set.of("b"),tracker.matured(1700));}
    @Test public void invalidMeasurementsFailClosed(){FeedExposureTracker tracker=new FeedExposureTracker();Map<String,Double> values=new HashMap<>();values.put(null,1.0);values.put("",1.0);values.put("nan",Double.NaN);values.put("over",1.1);values.put("missing",null);tracker.viewport(values,0);assertEquals(-1,tracker.dueAt());tracker.viewport(Map.of("a",1.0),100);assertTrue(tracker.matured(99).isEmpty());assertEquals(-1,tracker.dueAt());tracker.viewport(Map.of("a",1.0),200);assertTrue(tracker.matured(-1).isEmpty());assertEquals(-1,tracker.dueAt());}
    @Test public void noCallbackRemainsAfterAllRowsLeave(){FeedExposureTracker tracker=new FeedExposureTracker();tracker.viewport(Map.of("a",1.0),0);tracker.viewport(Map.of(),500);assertEquals(-1,tracker.dueAt());assertTrue(tracker.matured(2000).isEmpty());}
    @Test public void onePresentationCannotGrowMemoryWithoutBound(){FeedExposureTracker tracker=new FeedExposureTracker();long time=0;int recorded=0;for(int n=0;n<FeedExposureTracker.MAX_REPORTED+100;n++){tracker.viewport(Map.of("item-"+n,1.0),time);time+=1200;recorded+=tracker.matured(time).size();}assertEquals(FeedExposureTracker.MAX_REPORTED,recorded);assertEquals(-1,tracker.dueAt());tracker.newPresentation();tracker.viewport(Map.of("new",1.0),time);assertEquals(Set.of("new"),tracker.matured(time+1200));}
}
